'use strict';

// MODULES //

var contains = require( '@stdlib/array/base/assert/contains' ).factory;


// VARIABLES //

var CLASSIFICATION_LOSS_FNS = [
	'epsilon-insensitive',
	'hinge',
	'huber',
	'log',
	'modified-huber',
	'perceptron',
	'squared-epsilon-insensitive',
	'squared-error',
	'squared-hinge'
];


// MAIN //

/**
* Tests whether an input value is a supported classification loss function.
*
* @name isClassificationLossFn
* @type {Function}
* @param {*} v - value to test
* @returns {boolean} boolean indicating whether an input value is a supported classification loss function
*
* @example
* var bool = isClassificationLossFn( 'epsilon-insensitive' );
* // returns true
*
* bool = isClassificationLossFn( 'hinge' );
* // returns true
*
* bool = isClassificationLossFn( 'huber' );
* // returns true
*
* bool = isClassificationLossFn( 'log' );
* // returns true
*
* bool = isClassificationLossFn( 'modified-huber' );
* // returns true
*
* bool = isClassificationLossFn( 'perceptron' );
* // returns true
*
* bool = isClassificationLossFn( 'squared-epsilon-insensitive' );
* // returns true
*
* bool = isClassificationLossFn( 'squared-error' );
* // returns true
*
* bool = isClassificationLossFn( 'squared-hinge' );
* // returns true
*
* bool = isClassificationLossFn( 'foo' );
* // returns false
*/
var isClassificationLossFn = contains( CLASSIFICATION_LOSS_FNS );


// EXPORTS //

module.exports = isClassificationLossFn;
